// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title CrossServiceAuthenticator
 * @notice Manages authentication tokens for mobile backend API services
 * @dev Uses on-chain entropy accumulation for session token generation
 */
contract CrossServiceAuthenticator is Ownable {
    using ECDSA for bytes32;

    struct Session {
        address user;
        uint256 tokenHash;
        uint256 expiry;
        uint8 serviceLevel;
    }

    struct EntropyPool {
        uint256 accumulator;
        uint256 mixCount;
        uint256 lastMixBlock;
        bytes32 seedCommitment;
    }

    mapping(bytes32 => Session) public sessions;
    mapping(address => EntropyPool) private entropyPools;
    mapping(address => bool) public registeredServices;
    mapping(address => uint256) private serviceNonces;

    uint256 private constant SESSION_DURATION = 3600;
    uint256 private constant MIN_MIX_INTERVAL = 1;
    uint256 private constant ENTROPY_ROUNDS = 8;

    event SessionCreated(address indexed user, bytes32 indexed sessionId, uint256 expiry);
    event EntropyMixed(address indexed service, uint256 mixCount);
    event ServiceRegistered(address indexed service);

    modifier onlyRegisteredService() {
        require(registeredServices[msg.sender], "Not a registered service");
        _;
    }

    constructor() Ownable() {
        // Initialize with deployment entropy
        entropyPools[address(this)] = EntropyPool({
            accumulator: uint256(keccak256(abi.encodePacked(block.timestamp, block.prevrandao, msg.sender))),
            mixCount: 1,
            lastMixBlock: block.number,
            seedCommitment: keccak256(abi.encodePacked(block.prevrandao))
        });
    }

    function registerService(address service) external onlyOwner {
        require(service != address(0), "Invalid service address");
        require(service != address(this), "Cannot register contract itself");
        require(!registeredServices[service], "Service already registered");
        registeredServices[service] = true;
        entropyPools[service] = EntropyPool({
            accumulator: uint256(keccak256(abi.encodePacked(
                entropyPools[address(this)].accumulator,
                service,
                block.number
            ))),
            mixCount: 0,
            lastMixBlock: block.number,
            seedCommitment: bytes32(0)
        });
        emit ServiceRegistered(service);
    }

    /**
     * @notice Contributes entropy to the service's pool
     * @param entropyContribution External entropy from the service
     */
    function contributeEntropy(bytes32 entropyContribution) external onlyRegisteredService {
        EntropyPool storage pool = entropyPools[msg.sender];
        require(block.number >= pool.lastMixBlock + MIN_MIX_INTERVAL, "Too frequent");

        pool.accumulator = _mixEntropy(
            pool.accumulator,
            uint256(entropyContribution),
            block.prevrandao
        );
        pool.mixCount++;
        pool.lastMixBlock = block.number;
        pool.seedCommitment = keccak256(abi.encodePacked(
            pool.seedCommitment,
            entropyContribution
        ));

        emit EntropyMixed(msg.sender, pool.mixCount);
    }

    /**
     * @notice Creates an authenticated session token
     * @param user The user address requesting authentication
     * @param serviceSignature Signature from the requesting service
     * @return sessionId The generated session identifier
     * @return tokenSeed The seed for deriving the bearer token off-chain
     */
    function createSession(
        address user,
        bytes calldata serviceSignature
    ) external onlyRegisteredService returns (bytes32 sessionId, uint256 tokenSeed) {
        require(user != address(0), "Invalid user address");
        // Verify service signature over the user address with nonce
        uint256 nonce = serviceNonces[msg.sender]++;
        bytes32 messageHash = keccak256(abi.encodePacked(user, block.chainid, address(this), nonce));
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        require(ethSignedHash.recover(serviceSignature) == msg.sender, "Invalid service signature");

        // Generate token using entropy pool
        tokenSeed = _generateToken(msg.sender, user, nonce);
        sessionId = keccak256(abi.encodePacked(user, msg.sender, tokenSeed));

        sessions[sessionId] = Session({
            user: user,
            tokenHash: uint256(keccak256(abi.encodePacked(tokenSeed))),
            expiry: block.timestamp + SESSION_DURATION,
            serviceLevel: _getServiceLevel(msg.sender)
        });

        emit SessionCreated(user, sessionId, block.timestamp + SESSION_DURATION);
        return (sessionId, tokenSeed);
    }

    /**
     * @notice Validates a session token
     * @param sessionId The session to validate
     * @param tokenProof Hash proof of the token
     */
    function validateSession(
        bytes32 sessionId,
        uint256 tokenProof
    ) external view returns (bool valid, address user, uint8 serviceLevel) {
        Session storage session = sessions[sessionId];
        if (session.expiry == 0 || block.timestamp > session.expiry) {
            return (false, address(0), 0);
        }
        if (session.tokenHash != uint256(keccak256(abi.encodePacked(tokenProof)))) {
            return (false, address(0), 0);
        }
        return (true, session.user, session.serviceLevel);
    }

    /**
     * @dev Core token generation using accumulated entropy
     * @notice Applies multiple rounds of mixing for security
     */
    function _generateToken(address service, address user, uint256 nonce) internal returns (uint256) {
        EntropyPool storage pool = entropyPools[service];
        EntropyPool storage globalPool = entropyPools[address(this)];

        // Derive base from service pool state combined with prevrandao
        uint256 token = uint256(keccak256(abi.encodePacked(
            pool.accumulator,
            block.prevrandao,
            nonce
        )));

        // Apply mixing rounds
        for (uint256 i = 0; i < ENTROPY_ROUNDS; i++) {
            token = _mixEntropy(
                token,
                uint256(keccak256(abi.encodePacked(
                    globalPool.accumulator,
                    user,
                    pool.mixCount,
                    block.prevrandao,
                    i
                ))),
                uint256(blockhash(block.number - 1))
            );
        }

        // Update pool state with prevrandao for forward secrecy
        pool.accumulator = uint256(keccak256(abi.encodePacked(pool.accumulator, block.prevrandao, block.number)));
        globalPool.accumulator = uint256(keccak256(abi.encodePacked(globalPool.accumulator, token, block.prevrandao)));

        return token;
    }

    /**
     * @dev Entropy mixing function using xorshift-style operations
     */
    function _mixEntropy(
        uint256 state,
        uint256 input,
        uint256 auxiliary
    ) internal pure returns (uint256) {
        uint256 mixed = state ^ input;
        mixed = mixed ^ (mixed << 13);
        mixed = mixed ^ (mixed >> 7);
        mixed = mixed ^ (mixed << 17);
        // Fold in auxiliary data
        mixed = uint256(keccak256(abi.encodePacked(mixed, auxiliary)));
        return mixed;
    }

    function _getServiceLevel(address service) internal view returns (uint8) {
        uint256 mixCount = entropyPools[service].mixCount;
        if (mixCount >= 100) return 3;
        if (mixCount >= 10) return 2;
        return 1;
    }

    function getPoolInfo(address service) external view onlyOwner returns (
        uint256 mixCount,
        uint256 lastMixBlock,
        bytes32 seedCommitment
    ) {
        EntropyPool storage pool = entropyPools[service];
        return (pool.mixCount, pool.lastMixBlock, pool.seedCommitment);
    }
}
